function Assert-Root([string]$Path,[string]$Name,[bool]$MustExist=$true) { if(-not[IO.Path]::IsPathRooted($Path)){throw "$Name must be absolute."};$full=[IO.Path]::GetFullPath($Path).TrimEnd('\','/');$boundary=[IO.Path]::GetDirectoryName($repositoryRoot).TrimEnd('\','/');if(-not$full.StartsWith("$boundary\",[StringComparison]::OrdinalIgnoreCase)){throw "$Name is outside the approved project-parent trust boundary."};if($MustExist-and-not(Test-Path -LiteralPath $full -PathType Container)){throw "$Name must be an existing directory."};$ancestor=if(Test-Path $full){Get-Item -LiteralPath $full -Force}else{Get-Item -LiteralPath ([IO.Path]::GetDirectoryName($full)) -Force};while($null-ne$ancestor){if(($ancestor.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw "$Name traverses a reparse-point."};if($ancestor.FullName.TrimEnd('\','/').Equals($boundary,[StringComparison]::OrdinalIgnoreCase)){break};$ancestor=$ancestor.Parent};if(Test-Path $full){foreach($item in @(Get-ChildItem -LiteralPath $full -Force -Recurse)){if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw "$Name contains a reparse-point."}}};$full }
