function Optional([object]$Value,[string]$Name) { $property=$Value.PSObject.Properties[$Name];if($null-eq$property){$null}else{$property.Value} }
function Run([string]$Exe,[string[]]$Tokens,[string]$Name) { $stdout=Join-Path $logs "$Name.stdout.txt";$stderr=Join-Path $logs "$Name.stderr.txt";& $Exe @Tokens 1>$stdout 2>$stderr;[ordered]@{ executable=$Exe; arguments=$Tokens; exitCode=$LASTEXITCODE; stdout=[ordered]@{path="logs/$([IO.Path]::GetFileName($stdout))";size=(Get-Item $stdout).Length;sha256=(Hash $stdout)};stderr=[ordered]@{path="logs/$([IO.Path]::GetFileName($stderr))";size=(Get-Item $stderr).Length;sha256=(Hash $stderr)} } }
function Parse-DecimalInvariant([object]$Value,[string]$Label) { $number=[decimal]0;if($null-eq$Value-or-not[decimal]::TryParse([string]$Value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$number)){throw "$Label is not an invariant decimal."};$number }
